def transform(grid):
    h, w = len(grid), len(grid[0])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    out = [row[:] for row in grid]
    if not pts:
        return out

    row_counts = {}
    col_counts = {}
    for r, c in pts:
        row_counts[r] = row_counts.get(r, 0) + 1
        col_counts[c] = col_counts.get(c, 0) + 1

    best_row = max(row_counts, key=row_counts.get)
    best_col = max(col_counts, key=col_counts.get)

    # Select the line containing the greatest number of points.
    horizontal = row_counts[best_row] > col_counts[best_col]
    if horizontal:
        br = best_row
        cols = [c for r, c in pts if r == br]
        left, right = min(cols), max(cols)
        for c in range(left, right + 1):
            if out[br][c] == 0:
                out[br][c] = 3
        for r, c in pts:
            if r != br:
                for rr in range(min(r, br), max(r, br) + 1):
                    if out[rr][c] == 0:
                        out[rr][c] = 3
    else:
        bc = best_col
        rows = [r for r, c in pts if c == bc]
        top, bottom = min(rows), max(rows)
        for r in range(top, bottom + 1):
            if out[r][bc] == 0:
                out[r][bc] = 3
        for r, c in pts:
            if c != bc:
                for cc in range(min(c, bc), max(c, bc) + 1):
                    if out[r][cc] == 0:
                        out[r][cc] = 3
    return out
